const transcript = $input.first().json.transcript;

// Total duration from the last segment
const lastSegment = transcript[transcript.length - 1];
const totalDurationSeconds = lastSegment.start + (lastSegment.duration || 0);

function formatTime(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  return [h, m, s].map(n => String(n).padStart(2, '0')).join(':');
}

// Pick chunk size based on total length so short videos get finer
// detail and long videos get coarser (but still many) chapters
let chunkMinutes;
if (totalDurationSeconds <= 20 * 60) {
  chunkMinutes = 5;
} else if (totalDurationSeconds <= 60 * 60) {
  chunkMinutes = 10;
} else {
  chunkMinutes = 15;
}
const chunkSeconds = chunkMinutes * 60;

// Group transcript segments into time-based chunks
const chunks = [];
let currentChunk = [];
let chunkStart = 0;

for (const segment of transcript) {
  if (segment.start >= chunkStart + chunkSeconds && currentChunk.length > 0) {
    chunks.push({
      startTime: formatTime(chunkStart),
      endTime: formatTime(segment.start),
      text: currentChunk.map(s => s.text).join(' ')
    });
    chunkStart += chunkSeconds;
    currentChunk = [];
  }
  currentChunk.push(segment);
}
if (currentChunk.length > 0) {
  chunks.push({
    startTime: formatTime(chunkStart),
    endTime: formatTime(totalDurationSeconds),
    text: currentChunk.map(s => s.text).join(' ')
  });
}

const chapteredTranscript = chunks
  .map(c => `[${c.startTime} - ${c.endTime}]\n${c.text}`)
  .join('\n\n');

return [
  {
    json: {
      totalDuration: formatTime(totalDurationSeconds),
      chapterCount: chunks.length,
      chapteredTranscript
    }
  }
];

